UPDATE user_quota
SET interview_free_used = interview_free_used + 1,
    update_time = NOW()
WHERE user_id = #{userId}
  AND deleted = false
  AND interview_free_used < #{limit}

UPDATE user_quota
SET resume_chat_free_used = resume_chat_free_used + 1,
    update_time = NOW()
WHERE user_id = #{userId}
  AND deleted = false
  AND resume_chat_free_used < #{limit}
